export class Scope{constructor(bundle,errors,args){this.dirty=new WeakSet;this.params=null;this.placeables=0;this.bundle=bundle;this.errors=errors;this.args=args}reportError(error){if(!this.errors||!(error instanceof Error)){throw error}this.errors.push(error)}memoizeIntlObject(ctor,opts){let cache=this.bundle._intls.get(ctor);if(!cache){cache={};this.bundle._intls.set(ctor,cache)}let id=JSON.stringify(opts);if(!cache[id]){cache[id]=new ctor(this.bundle.locales,opts)}return cache[id]}}